// This builds a bulleted or numbered list from an array
function makeList(items, ordered) {
  const tag = ordered ? "ol" : "ul";
  const lis = items.map(function(item) { return "<li>" + item + "</li>"; }).join("");
  return "<" + tag + ">" + lis + "</" + tag + ">";
}
console.log(makeList(["Eggs", "Milk"], false));
console.log(makeList(["Post", "Pick"], true));

