// This builds one table row from an array of cell values
function makeRow(cells) {
  const tds = cells.map(function(c) { return "<td>" + c + "</td>"; }).join("");
  return "<tr>" + tds + "</tr>";
}
console.log(makeRow(["Roli", "Calgary"]));

